// Icons in place of the emoji the interface labels things with, in a pack you choose (Settings › Appearance):
//   line    – Lucide line icons (ISC licence), drawn in the text colour. The default.
//   color   – Fluent Emoji Flat (Microsoft, MIT licence): flat, colourful, the same on every phone.
//   material – Material Symbols Rounded (Google, Apache 2.0): filled, the look of Android itself.
//   duotone – Phosphor Duotone (MIT): two-tone line icons, the second tone in the accent colour.
// The optional packs are loaded on first use (src/icons-*.js, generated by scripts/build-color-icons.mjs).
//   emoji   – the phone's own emoji, as written.
//
// The labels are still written with emoji in the source – short, readable, and the words beside them stay what
// tests and screen readers see. iconize() swaps each known emoji in the interface for the matching Lucide icon,
// drawn in the text colour. Content is never touched: messages, code, inputs, persona avatars and anything the
// user wrote keep their emoji. An emoji with no entry here stays as it is.
import {
  AppWindow, Ban, Bandage, Bell, BookOpen, Bot, Brain, BrushCleaning, Calendar, Camera, ChartColumn, Check, CircleHelp,
  CircleStop, Clapperboard, Clock, Compass, Download, ExternalLink, Eye, EyeOff, FileCode, FilePenLine, FileText,
  FlaskConical, Folder, FolderOpen, Folders, GitBranch, GitFork, Glasses, Globe, GraduationCap, Handshake, Hourglass,
  Image, KeyRound, Laptop, Library, Lightbulb, Link, LockKeyhole, Lock, Map as MapIcon, Menu, MessageCircle, Mic,
  Microscope, Monitor, Package, Palette, Paperclip, PenLine, Pencil, Pin, Plug, Plus, Puzzle, Recycle, Redo2, RefreshCw,
  Repeat, Replace, Save, ScrollText, Search, Settings, Shield, SlidersHorizontal, Smartphone, Sparkles, Square,
  SquareCheck, SquareTerminal, Star, Stethoscope, Target, Toolbox, Trash2, TriangleAlert, Type, Undo2, Upload, User,
  ClipboardList, Users, VenetianMask, Volume2, Webhook, WifiOff, Wrench, WrapText, X, Zap, AudioLines, Smile,
  AlarmClock, Scissors, Rewind, Play, Share, Import,
  Wifi, MapPin, BatteryMedium, Mail, Phone,
} from 'lucide';

const svg = (node) =>
  `<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${node
    .map(([tag, attrs]) => `<${tag} ${Object.entries(attrs).map(([k, v]) => `${k}="${v}"`).join(' ')}/>`)
    .join('')}</svg>`;

// one emoji, one meaning – except where the words after it say otherwise (rule: [test on the following text, icon])
const MAP = {
  '🎭': VenetianMask, '💬': MessageCircle, '🤖': Bot, '👤': User, '🧑': User, '👥': Users, '🙂': Smile,
  '📁': Folder, '📂': FolderOpen, '🗂': Folders, '📄': FileText, '📝': FilePenLine, '📜': ScrollText, '📋': ClipboardList,
  '📚': Library, '📖': BookOpen, '🐍': FileCode, '💻': Laptop, '🖥': Monitor, '🐧': SquareTerminal, '🪟': AppWindow,
  '📶': Wifi, '📍': MapPin, '🔋': BatteryMedium, '✉': Mail, '📞': Phone,
  '📱': Smartphone, '📲': Smartphone, '🌐': Globe, '🌍': Globe, '🔗': Link, '🔌': Plug, '🪝': Webhook, '📴': WifiOff,
  '🛠': Wrench, '🔧': Wrench, '🧰': Toolbox, '🧩': Puzzle, '🧪': FlaskConical, '🔬': Microscope, '🩺': Stethoscope, '🩹': Bandage,
  '🧠': Brain, '⚡': Zap, '✨': Sparkles, '🎯': Target, '💡': Lightbulb, '🎓': GraduationCap,
  '🛡': Shield, '🔐': LockKeyhole, '🔒': Lock, '🔑': KeyRound, '⛔': Ban, '👁': Eye, '🙈': EyeOff, '🕶': Glasses,
  '🔍': Search, '🔎': Search, '🧭': Compass, '🗺': MapIcon, '🤝': Handshake,
  '🔊': Volume2, '🎙': AudioLines, '🎤': Mic, '📷': Camera, '📸': Camera, '🖼': Image, '🎬': Clapperboard, '🎨': Palette, '🎛': SlidersHorizontal,
  '📊': ChartColumn, '🔤': Type, '📌': Pin, '📦': Package, '📎': Paperclip, '💾': Save, '📤': Upload, '📥': Download,
  '🗑': Trash2, '🧹': BrushCleaning, '♻': Recycle, '✏': Pencil, '✎': Pencil, '✍': PenLine, '➕': Plus,
  '🔔': Bell, '⏳': Hourglass, '🕘': Clock, '🗓': Calendar, '⏹': CircleStop, '⭐': Star, '⚙': Settings, '☰': Menu,
  '❓': CircleHelp, '⚠': TriangleAlert, '✓': Check, '✗': X, '✕': X, '☑': SquareCheck, '☐': Square, '↗': ExternalLink,
  '↻': RefreshCw, '🔄': RefreshCw, '↶': Undo2, '↪': Redo2,
  // these have no text glyph in Android's font: left alone they show as colour emoji among the line icons
  '⏰': AlarmClock, '✂': Scissors, '⏪': Rewind, '▶': Play, '⬇': Download, '⤴': Share, '⤵': Import,
  // a fork and git history were both 🌿: the words decide. [test, line icon, colourful stand-in]
  // [test, line icon, colourful stand-in, key in src/icon-names.js]
  '🌿': { rules: [[/\bgit\b|commit|history/i, GitBranch, '🕰', '🌿git']], else: GitFork, color: '🔀' },
  '🔁': { rules: [[/regex|replace/i, Replace, '🔤', '🔁regex'], [/retry/i, RefreshCw, '🔄', '🔁retry']], else: Repeat },
  '↩': { rules: [[/wrap/i, WrapText, '↩', '↩wrap']], else: Undo2 },
};
// the colourful pack draws these symbols with their emoji cousin (☰ and ☐ have none: they stay line icons)
const COLOR_ALT = { '✓': '✅', '✗': '❌', '✕': '❌', '☑': '☑', '↻': '🔄', '↶': '↩', '↪': '↪', '↗': '↗', '✎': '✏', '🧑': '👤' };
// end of the table
const PACKS = {
  color: () => import('./icons-color.js'),
  material: () => import('./icons-material.js'),
  duotone: () => import('./icons-duotone.js'),
};
let pack = 'line';
const loaded = {}; // pack -> { viewBox, icons }
const cache = new Map();
/** The variant an emoji stands for here: { line, color, key } – or null when it is not one of ours. */
function variant(emoji, after = '') {
  const e = emoji.replace(/\uFE0F/g, '');
  const v = MAP[e];
  if (!v) return null;
  if (!v.rules) return { line: v, color: COLOR_ALT[e] || e, key: e };
  const r = v.rules.find(([rx]) => rx.test(after));
  return r ? { line: r[1], color: r[2] || e, key: r[3] || e } : { line: v.else, color: v.color || e, key: e };
}
function draw(emoji, v) {
  if (pack === 'emoji') return null;
  const p = loaded[pack];
  if (p) {
    const body = pack === 'color' ? p.icons[v.color] || p.icons[emoji.replace(/\uFE0F/g, '')] : p.icons[v.key];
    // a pack without this one falls back to the line icon
    if (body) return `<svg class="ic ic-${pack}" viewBox="${p.viewBox}" fill="currentColor" aria-hidden="true">${body}</svg>`;
  }
  if (!cache.has(v.line)) cache.set(v.line, svg(v.line));
  return cache.get(v.line);
}
/** The icon (an <svg> string) for an emoji in the chosen pack, given the words after it – or null. */
export function iconFor(emoji, after = '') {
  const v = variant(emoji, after);
  return v ? draw(emoji, v) : null;
}
/** An icon by emoji, for code that builds a label itself. */
export const icon = (emoji, after = '') => iconFor(emoji, after) || emoji;

const KEYS = Object.keys(MAP).sort((a, b) => b.length - a.length);
const RX = new RegExp(`(${KEYS.map((k) => k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|')})\uFE0F?`, 'u');
// never inside these: what people wrote, what the model wrote, code, avatars, the terminal
const SKIP = '.map-card, .ic-wrap, .bubble, .md, pre, code, textarea, input, select, option, [contenteditable], .avatar, .cv-emoji, .pe-avatar, .xterm, .no-icons, .ic, script, style, #messages .tool-body, .tool-out, .mem-text, .conv-name, .sched-prompt, .sched-history';

function swapText(t) {
  const s = t.nodeValue;
  if (!s || !RX.test(s)) return;
  const p = t.parentElement;
  if (!p || p.closest(SKIP)) return;
  const frag = document.createDocumentFragment();
  let rest = s;
  for (let m = RX.exec(rest); m; m = RX.exec(rest)) {
    const after = rest.slice(m.index + m[0].length);
    if (m.index) frag.append(rest.slice(0, m.index));
    // the emoji stays in the text, hidden: code and tests that read a label still find it, and copying it works.
    // The words after it are kept for switching packs (they decide 🌿 fork / git).
    const span = document.createElement('span');
    span.className = 'ic-wrap';
    span.dataset.after = after.slice(0, 40);
    paint(span, m[0]);
    frag.append(span);
    rest = after;
  }
  if (rest) frag.append(rest);
  t.replaceWith(frag);
}

function paint(span, emoji) {
  const ic = iconFor(emoji, span.dataset.after || '');
  span.classList.toggle('ic-plain', !ic);
  span.innerHTML = ic ? ic + `<span class="ic-e">${emoji}</span>` : `<span class="ic-plain-e">${emoji}</span>`;
}

export const ICON_PACKS = ['line', 'color', 'material', 'duotone', 'emoji'];
/** Use another pack (one of ICON_PACKS). Everything already on screen is redrawn. */
export async function setIconPack(name) {
  const want = ICON_PACKS.includes(name) ? name : 'line';
  if (PACKS[want] && !loaded[want]) {
    const m = await PACKS[want]();
    loaded[want] = { viewBox: m.viewBox, icons: m.default };
  }
  pack = want;
  document.querySelectorAll('.ic-wrap').forEach((s) => paint(s, s.textContent));
}
export const iconPack = () => pack;

/** Swap the interface emoji under root (an element or the document) for line icons. */
export function iconize(root = document.body) {
  if (!root) return;
  if (root.nodeType === 3) return swapText(root);
  if (root.nodeType !== 1 || root.closest?.(SKIP)) return;
  // whole subtrees of content are passed over without looking inside (a long reply streams in many times a second)
  const w = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT | NodeFilter.SHOW_TEXT, {
    acceptNode: (n) => (n.nodeType === 1 ? (n.matches(SKIP) ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_SKIP) : RX.test(n.nodeValue || '') ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_SKIP),
  });
  const todo = [];
  for (let n = w.nextNode(); n; n = w.nextNode()) todo.push(n);
  todo.forEach(swapText);
}

/**
 * Keep doing it as the interface changes: new sheets, redrawn lists, labels that change. The swap happens in the
 * observer's own callback – a microtask, so before the browser paints. (Waiting for the next animation frame showed
 * the raw emoji for one frame whenever the change itself was made in a frame callback, as a streaming reply's tool
 * cards are: the icons flickered and the text beside them jumped.)
 */
export function watchIcons(root = document.body) {
  iconize(root);
  new MutationObserver((list) => {
    const pending = new Set();
    for (const m of list) {
      if (m.type === 'characterData') pending.add(m.target);
      for (const n of m.addedNodes) {
        if (n.nodeType === 1 && n.classList?.contains('ic-wrap')) continue;
        if (n.nodeType === 3 || n.nodeType === 1) pending.add(n);
      }
    }
    for (const n of pending) if (n.isConnected) iconize(n);
  }).observe(root, { childList: true, subtree: true, characterData: true });
}
